const BASE_URL = "https://api-sandbox.asaas.com"; // produção: https://api.asaas.com
const API_KEY = process.env.ASAAS_API_KEY ?? "<<SUA_API_KEY>>";

async function asaas<T>(method: string, path: string, body?: unknown, tentativas = 3): Promise<T | null> {
  for (let i = 0; i < tentativas; i++) {
    const res = await fetch(BASE_URL + path, {
      method,
      headers: { access_token: API_KEY, "User-Agent": "minha-integracao/1.0", "Content-Type": "application/json" },
      body: body === undefined ? undefined : JSON.stringify(body),
    });
    const ultima = i === tentativas - 1;
    if (res.status === 429 && !ultima) {
      const espera = Number(res.headers.get("RateLimit-Reset") ?? "5") + 1;
      await new Promise((r) => setTimeout(r, espera * 1000));
      continue;
    }
    if (res.status >= 500 && method === "GET" && !ultima) {
      await new Promise((r) => setTimeout(r, 2 ** i * 1000));
      continue;
    }
    const texto = await res.text();
    if (!res.ok) throw new Error(`Asaas HTTP ${res.status}: ${texto}`);
    return texto ? (JSON.parse(texto) as T) : null;
  }
  throw new Error("Asaas: tentativas esgotadas");
}

const payload = {
  "name": "Cliente Exemplo Ltda",
  "cpfCnpj": "00000000000191",
  "email": "financeiro@example.com",
  "mobilePhone": "11900000000",
  "postalCode": "01001000",
  "addressNumber": "100",
  "externalReference": "CLI-001",
  "notificationDisabled": false
};

// Sem idempotência na API: em timeout, consulte antes de reenviar.
asaas("POST", "/v3/customers", payload).then(console.log).catch(console.error);

