    return texto ? (JSON.parse(texto) as T) : null;
  }
  throw new Error("Asaas: tentativas esgotadas");
}

type Pagina = { hasMore?: boolean; data: Record<string, unknown>[] };

export async function listarTodos(): Promise<Record<string, unknown>[]> {
  const itens: Record<string, unknown>[] = [];
  for (let offset = 0; ; offset += 100) {
    const page = await asaas<Pagina>("GET", `/v3/customers?limit=100&offset=${offset}`);
    itens.push(...(page?.data ?? []));
    if (!page?.hasMore) return itens;
  }
}

listarTodos().then((r) => console.log(r.length, "registros")).catch(console.error);

